"""Database model for 0-6 hour convective nowcasting forecast frames."""

import uuid
from datetime import datetime
from sqlalchemy import Column, String, Integer, Float, DateTime, ForeignKey, Index
from sqlalchemy.dialects.postgresql import UUID, JSONB
from geoalchemy2 import Geometry
from apps.api.core.database import Base


class Forecast(Base):
    """Spatio-temporal convective forecast frames generated by ML models."""

    __tablename__ = "forecasts"

    id = Column(UUID(as_uuid=True), primary_key=True, default=uuid.uuid4)
    model_run_id = Column(UUID(as_uuid=True), ForeignKey("model_runs.id", ondelete="SET NULL"), nullable=True, index=True)

    sector_id = Column(String(32), nullable=False, index=True)
    base_time = Column(DateTime, nullable=False, index=True)  # Observation anchor T-0
    forecast_time = Column(DateTime, nullable=False, index=True)  # Target nowcast time
    lead_time_minutes = Column(Integer, nullable=False)  # 10, 20, 30... 360

    # Bounding spatial extent of the forecast grid
    extent = Column(Geometry(geometry_type="POLYGON", srid=4326), nullable=True)

    # Reference to pre-rendered raster tile or numpy tensor store
    raster_tile_path = Column(String(512), nullable=True)
    domain_max_dbz = Column(Float, nullable=True)
    confidence_index = Column(Float, nullable=False, default=1.0)  # 1.0 (high) to 0.0 (high uncertainty)

    metrics_summary = Column(JSONB, nullable=True)
    created_at = Column(DateTime, nullable=False, default=datetime.utcnow)

    __table_args__ = (
        Index("idx_forecasts_base_lead", base_time, lead_time_minutes),
        Index("idx_forecasts_forecast_time", forecast_time),
        Index("idx_forecasts_extent_gist", extent, postgresql_using="gist"),
    )
